-- Approved Q12/Q14/Q05 prospective predicate; stored flag correction in migration.
((CASE WHEN path LIKE '%/logicalChannelConfig/%/logicalChannelGroup' THEN false WHEN regexp_replace(path, '\[[0-9]+\]', '[*]', 'g') IN ('systemInformationBlockType1/cellAccessRelatedInfo/cellIdentity','systemInformationBlockType1/cellAccessRelatedInfo/plmn-IdentityList/[*]/plmn-Identity/mcc','systemInformationBlockType1/cellAccessRelatedInfo/plmn-IdentityList/[*]/plmn-Identity/mnc','systemInformationBlockType1/cellAccessRelatedInfo/trackingAreaCode') THEN true ELSE COALESCE(is_identifier,false) END) OR regexp_replace(path,'^.*/','') ~ '^(spare[0-9]*|dummy|reserved)$' OR path IN ('systemFrameNumber','mib/systemFrameNumber'))
